class Solution {
public:
    int getFood(vector<vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        queue<pair<int, int>> q;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == '*') { q.push({r, c}); grid[r][c] = 'X'; }
            }
        }
        int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
        int distance = 0;
        while (!q.empty()) {
            int count = q.size();
            while (count--) {
                auto cell = q.front(); q.pop();
                for (int d = 0; d < 4; ++d) {
                    int r = cell.first + dr[d], c = cell.second + dc[d];
                    if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] == 'X') continue;
                    if (grid[r][c] == '#') return distance + 1;
                    grid[r][c] = 'X';
                    q.push({r, c});
                }
            }
            ++distance;
        }
        return -1;
    }
};
